def word_count_ascii(text):
    words = []
    current = []
    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            if 'A' <= ch <= 'Z':
                current.append(chr(ord(ch) + 32))
            else:
                current.append(ch)
        else:
            if current:
                words.append(''.join(current))
                current = []
    if current:
        words.append(''.join(current))
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    pairs = [[w, counts[w]] for w in counts]
    pairs.sort(key=lambda x: x[0])
    return pairs
